"""Per-image paint masks, shared by the media loader, LoadImage and the phone.

A mask is stored once per *image path*, not per node: the same picture used in a
media loader, in a LoadImage and on the phone all see the same painted layer.
That keeps the workflow untouched (no new widgets, no state format change) and
means an old workflow loads with no masks at all.

The masks themselves live under ComfyUI's user directory
(``user/QQ_ComfyUI_Tools/masks/``), not in ``input``: they are the user's work
and must survive a restart, but they are not media files and must not clutter
the library. The throw-away alpha copies made for a plain LoadImage are written
to ``temp/`` while a prompt is submitted — one run only, removed by ComfyUI on
the next start — and nothing outside that prompt ever points at them.

Masks are 8-bit grayscale PNGs named after the hash of the image's path. White
means "keep", black means "drop", matching the convention ComfyUI's own MASK
outputs use.
"""

from __future__ import annotations

import hashlib
import os
from typing import Any

MASK_DIRECTORY_NAME = "masks"


def _input_root() -> str | None:
    try:
        import folder_paths

        return folder_paths.get_input_directory()
    except Exception:
        return None


def _user_root() -> str | None:
    """ComfyUI's user directory, where this extension keeps its own data."""
    try:
        import folder_paths

        base = folder_paths.get_user_directory()
    except Exception:
        return None
    if not base:
        return None
    return os.path.join(base, "QQ_ComfyUI_Tools")


def _mask_directory(create: bool = False) -> str | None:
    root = _user_root()
    if not root:
        return None
    directory = os.path.join(root, MASK_DIRECTORY_NAME)
    if create:
        try:
            os.makedirs(directory, exist_ok=True)
        except OSError:
            return None
    return directory if os.path.isdir(directory) else None


def normalize_image_reference(filename: str) -> str:
    """The reference a mask is keyed by: the path as the loaders see it."""
    return str(filename or "").replace("\\", "/").strip().lstrip("/")


def mask_key(filename: str) -> str:
    return hashlib.sha1(normalize_image_reference(filename).encode("utf-8")).hexdigest()


def mask_path(filename: str, create: bool = False) -> str | None:
    """Absolute path of the stored mask for one image, whether or not it exists."""
    directory = _mask_directory(create=create)
    if not directory:
        return None
    return os.path.join(directory, mask_key(filename) + ".png")


def mask_exists(filename: str) -> bool:
    path = mask_path(filename)
    return bool(path and os.path.isfile(path))


def mask_signature(filename: str) -> tuple[str, int, int] | None:
    """mtime+size, so a re-painted mask invalidates a cached node result."""
    path = mask_path(filename)
    if not path:
        return None
    try:
        stat = os.stat(path)
    except OSError:
        return None
    return (path, stat.st_mtime_ns, stat.st_size)


def load_mask_tensor(filename: str, height: int, width: int) -> "Any":
    """The stored mask as a ``[1, height, width]`` float tensor, or all-ones.

    Missing mask means "keep everything": a picture without a painted layer must
    behave exactly like before this feature existed.
    """
    import torch

    ones = torch.ones((1, height, width), dtype=torch.float32)
    path = mask_path(filename)
    if not path or not os.path.isfile(path):
        return ones
    try:
        from PIL import Image, ImageOps

        with Image.open(path) as image:
            image = ImageOps.exif_transpose(image)
            grey = image.convert("L")
            if grey.size != (width, height):
                grey = grey.resize((width, height), Image.LANCZOS)
            pixels = torch.frombuffer(bytearray(grey.tobytes()), dtype=torch.uint8)
    except Exception:
        return ones
    mask = pixels.reshape(1, height, width).float() / 255.0
    return mask


def save_mask_png(filename: str, payload: bytes) -> str | None:
    """Validate and store one painted mask; returns its path."""
    import io

    from PIL import Image

    try:
        with Image.open(io.BytesIO(payload)) as image:
            grey = image.convert("L")
            target = mask_path(filename, create=True)
            if not target:
                return None
            # Round-trip through a temp file so a half-written mask can never be
            # read by a running workflow.
            temp = target + ".tmp"
            grey.save(temp, format="PNG")
            os.replace(temp, target)
            return target
    except Exception:
        return None


def delete_mask(filename: str) -> bool:
    path = mask_path(filename)
    if not path:
        return False
    try:
        os.remove(path)
        return True
    except OSError:
        return False


def masked_image_filename(filename: str) -> str:
    """Name of the alpha-carrying copy made for a plain LoadImage.

    A ``LoadImage`` node takes its MASK from the PNG's alpha channel, and its
    outputs are fixed by ``RETURN_TYPES``, so a painted mask can only reach it
    through the file itself.

    The copy lives in ComfyUI's **temp** directory, not in ``input``: it is a
    throw-away artefact of one run, and temp is emptied on every start, so
    nothing accumulates in the user's library. A LoadImage value has to carry
    the ``[temp]`` suffix for ``get_annotated_filepath`` to look there.
    """
    stem, _extension = os.path.splitext(normalize_image_reference(filename))
    return f"{stem}_qqmask_{mask_key(filename)[:8]}.png"


def masked_reference(filename: str) -> str:
    """The value a LoadImage widget must hold to read the masked copy."""
    return f"{masked_image_filename(filename)} [temp]"


def _temp_directory() -> str | None:
    try:
        import folder_paths

        directory = folder_paths.get_temp_directory()
    except Exception:
        return None
    if not directory:
        return None
    try:
        os.makedirs(directory, exist_ok=True)
    except OSError:
        return None
    return directory


def write_masked_copy(filename: str) -> str | None:
    """Write the alpha-carrying copy of *filename* into temp.

    Called while a prompt is being submitted, not when the layer is painted:
    the copy is worth nothing before the run and is re-made on every run, so a
    picture never keeps a stale one.

    Returns the value the submitted prompt must carry (``"name [temp]"``), so
    the caller does not need to know about the annotation.
    """
    import numpy as np
    from PIL import Image, ImageOps

    source_path = _input_path(filename)
    if not source_path or not os.path.isfile(source_path):
        return None
    directory = _temp_directory()
    if not directory:
        return None
    target_path = os.path.join(directory, masked_image_filename(filename))
    try:
        with Image.open(source_path) as opened:
            image = ImageOps.exif_transpose(opened).convert("RGBA")
        width, height = image.size
        mask = load_mask_tensor(filename, height, width)
        alpha = (mask[0].clamp(0.0, 1.0).numpy() * 255.0).round().astype(np.uint8)
        image.putalpha(Image.fromarray(alpha, mode="L"))
        temp = target_path + ".tmp"
        image.save(temp, format="PNG")
        os.replace(temp, target_path)
        return masked_reference(filename)
    except Exception:
        return None


def clear_masked_copies(filename: str | None = None) -> int:
    """Remove generated copies from temp; returns how many went away.

    With *filename* only that picture's copy goes, which is what dropping a
    layer needs: the copy would otherwise still carry the old alpha.
    """
    directory = _temp_directory()
    if not directory:
        return 0
    wanted = masked_image_filename(filename) if filename else None
    removed = 0
    try:
        for item in os.listdir(directory):
            if "_qqmask_" not in item or not item.endswith(".png"):
                continue
            if wanted is not None and item != wanted:
                continue
            try:
                os.remove(os.path.join(directory, item))
                removed += 1
            except OSError:
                pass
    except OSError:
        return removed
    return removed


def _input_path(filename: str) -> str | None:
    """Absolute path of an input-directory file, refusing anything outside it."""
    root = _input_root()
    if not root:
        return None
    relative = normalize_image_reference(filename)
    if not relative or ".." in relative.split("/"):
        return None
    root_real = os.path.realpath(root)
    candidate = os.path.realpath(os.path.join(root, *relative.split("/")))
    if candidate != root_real and not candidate.startswith(root_real + os.sep):
        return None
    return candidate
